const page = "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <meta name=\"theme-color\" content=\"#07111f\" />\n    <title>Jarvis — Operations Center</title>\n    <meta name=\"description\" content=\"Evidence-first operations center for Jarvis.\" />\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />\n    <style>:root{--ink:#eaf2ff;--muted:#8d9aae;--line:#20314a;--panel:#0c192a;--panel2:#0f2037;--bg:#07111f;--cyan:#67e8f9;--amber:#fbbf24;--red:#fb7185}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(900px 400px at 85% -10%,#12345a55,transparent 65%),var(--bg);color:var(--ink);font-family:Manrope,system-ui,sans-serif}.shell{display:grid;grid-template-columns:242px minmax(0,1fr);min-height:100vh}.rail{position:sticky;top:0;height:100vh;border-right:1px solid var(--line);padding:30px 20px;display:flex;flex-direction:column;background:#07111fd9;backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font-weight:800;font-size:19px;letter-spacing:-1px}.brand-mark{display:grid;place-items:center;width:31px;height:31px;border:1px solid #61e9fc88;border-radius:8px;color:var(--cyan);font-family:'DM Mono';font-size:15px}.muted{color:var(--muted)}nav{display:grid;gap:5px;margin-top:56px}nav a{color:var(--muted);text-decoration:none;padding:10px 12px;border-radius:7px;font-size:13px;font-weight:600}nav a:hover,nav .active{background:#12325666;color:var(--ink)}.rail-note{margin-top:auto;border-top:1px solid var(--line);padding:18px 2px 0;color:#b6c3d6;font-size:12px;line-height:1.6}.rail-note small{color:var(--muted)}main{padding:42px clamp(24px,5vw,80px);max-width:1540px;width:100%;margin:auto}header{display:flex;justify-content:space-between;gap:30px;align-items:center;margin-bottom:36px}.eyebrow,.label{font-family:'DM Mono';font-size:10px;letter-spacing:1.1px;color:var(--cyan);margin:0 0 11px}h1{font-size:clamp(28px,3vw,43px);letter-spacing:-2px;margin:0}h2{font-size:clamp(21px,2vw,29px);letter-spacing:-1.2px;margin:0 0 13px}h3{margin:0 0 7px;font-size:16px}.header-actions{display:flex;gap:10px}.primary,.ghost,.outline,.disabled{border-radius:7px;padding:10px 14px;font:600 12px Manrope;cursor:pointer}.primary{border:0;background:var(--cyan);color:#062035}.ghost,.outline{background:transparent;border:1px solid #355170;color:var(--ink)}.ghost:hover,.outline:hover{border-color:var(--cyan);color:var(--cyan)}.panel{border:1px solid var(--line);background:linear-gradient(145deg,#0e2036d9,#0a1525d9);border-radius:12px}.hero{min-height:216px;padding:33px 36px;display:flex;align-items:center;justify-content:space-between;gap:36px;overflow:hidden;position:relative}.hero:after{content:'';position:absolute;width:260px;height:260px;border-radius:50%;border:1px solid #67e8f933;right:-70px;bottom:-150px;box-shadow:0 0 0 25px #67e8f908,0 0 0 60px #67e8f905}.state{display:flex;align-items:center;gap:11px;font-size:24px;letter-spacing:-.8px}.pulse{width:11px;height:11px;background:var(--amber);border-radius:50%;box-shadow:0 0 0 5px #fbbf2424}.hero-copy{max-width:590px;color:#b3c2d6;font-size:14px;line-height:1.75;margin:13px 0 0}.last-check{position:relative;z-index:1;border-left:1px solid #39516c;padding-left:24px;display:grid;gap:8px;min-width:220px}.last-check span,.last-check small{font-family:'DM Mono';font-size:10px;color:var(--muted)}.last-check strong{font-size:13px}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:13px 0 70px}.metric{padding:18px;border:1px solid var(--line);border-radius:10px;background:#0b1829}.metric-top{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:11px}.metric strong{display:block;font-size:21px;letter-spacing:-.6px;margin:17px 0 8px}.metric small{color:#8fa0b6;font-size:11px;line-height:1.5}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;flex:none}.unknown{background:var(--amber)}.failed{background:var(--red)}.split,.two-col{display:grid;grid-template-columns:.8fr 1.2fr;gap:50px;align-items:start}.section{margin-top:70px}.section-copy{margin:0;color:#95a7bc;font-size:13px;line-height:1.75;max-width:500px}.ledger{overflow:hidden}.ledger-row{display:grid;grid-template-columns:1.1fr .7fr 1.2fr;gap:15px;padding:15px 18px;border-bottom:1px solid var(--line);align-items:center;font-size:12px}.ledger-row:last-child{border:0}.ledger-row.heading{padding:12px 18px;color:var(--muted);font:10px 'DM Mono';letter-spacing:.7px}.status{width:max-content;padding:4px 7px;border-radius:4px;font:10px 'DM Mono'}.unknown-tag{color:#fcd34d;background:#f59e0b1c}.failed-tag{color:#fda4af;background:#fb71851c}.padded{padding:28px}.empty{margin-top:30px;padding:18px;color:var(--muted);font:11px 'DM Mono';border:1px dashed #39516c;border-radius:7px}.empty span{color:var(--cyan);margin-right:9px}.reason-list{list-style:none;padding:0;margin:24px 0 0;display:grid;gap:19px}.reason-list li{display:grid;grid-template-columns:30px 1fr;gap:9px}.reason-list li>span{color:var(--cyan);font:11px 'DM Mono';padding-top:2px}.reason-list strong{font-size:13px;display:block}.reason-list small{display:block;color:var(--muted);font-size:11px;line-height:1.5;margin-top:5px}.notification{display:flex;justify-content:space-between;gap:25px;align-items:center}.disabled{cursor:not-allowed;border:1px solid #38506a;background:#142235;color:#7e90a7;white-space:nowrap}.recovery{display:grid;grid-template-columns:.8fr 1.2fr;gap:50px}.steps{display:grid;gap:10px}.step{display:grid;grid-template-columns:43px 1fr;gap:14px;padding:20px;border:1px solid var(--line);border-radius:9px;background:#0b1829}.step>span{display:grid;place-items:center;width:29px;height:29px;border:1px solid #3d668c;border-radius:6px;color:var(--cyan);font:12px 'DM Mono'}.step p{color:var(--muted);font-size:12px;line-height:1.6;margin:0 0 13px}.outline{padding:6px 9px;font-size:10px}footer{border-top:1px solid var(--line);margin-top:70px;padding:24px 0;color:var(--muted);font:10px 'DM Mono';display:flex;justify-content:space-between;gap:15px}dialog{max-width:510px;width:calc(100% - 32px);background:#0c1a2d;color:var(--ink);border:1px solid #406180;border-radius:10px;padding:0;box-shadow:0 30px 90px #000b}dialog::backdrop{background:#020811bb}.modal-head{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--line)}#close-modal{background:transparent;border:0;color:var(--ink);font-size:24px;cursor:pointer}#modal-body{padding:20px;color:#b2c1d4;font-size:13px;line-height:1.7}#modal-body ul{padding-left:19px;margin:0;display:grid;gap:9px}@media(max-width:850px){.shell{display:block}.rail{position:static;height:auto;padding:16px 20px;border-right:0;border-bottom:1px solid var(--line)}nav{display:flex;overflow:auto;margin:16px 0 0}.rail-note{display:none}main{padding:28px 20px}header,.hero,.notification{align-items:flex-start;flex-direction:column}.metric-grid{grid-template-columns:repeat(2,1fr);margin-bottom:48px}.split,.two-col,.recovery{grid-template-columns:1fr;gap:25px}.section{margin-top:50px}.last-check{border-left:0;padding-left:0}.hero{padding:25px}.header-actions{width:100%}.header-actions button{flex:1}.ledger-row{grid-template-columns:1fr .7fr}.ledger-row span:last-child{grid-column:1/-1;color:var(--muted)}}@media(max-width:440px){.metric-grid{grid-template-columns:1fr}footer{flex-direction:column}.header-actions{flex-direction:column}}\n</style>\n  </head>\n  <body>\n    <div class=\"shell\">\n      <aside class=\"rail\">\n        <a class=\"brand\" href=\"#overview\"><span class=\"brand-mark\">J</span><span>jarvis<span class=\"muted\">/ops</span></span></a>\n        <nav aria-label=\"Operations navigation\">\n          <a class=\"active\" href=\"#overview\">Overview</a>\n          <a href=\"#evidence\">Evidence ledger</a>\n          <a href=\"#tasks\">Autonomy</a>\n          <a href=\"#notifications\">Notifications</a>\n          <a href=\"#recovery\">Recovery guide</a>\n        </nav>\n        <div class=\"rail-note\"><span class=\"dot unknown\"></span>Observation-only baseline<br /><small>No production actions are enabled.</small></div>\n      </aside>\n      <main>\n        <header>\n          <div><p class=\"eyebrow\">JARVIS CONTROL PLANE</p><h1>Operations, with proof.</h1></div>\n          <div class=\"header-actions\"><button class=\"ghost\" data-scroll=\"evidence\">View evidence</button><button class=\"primary\" data-scroll=\"recovery\">Start guided recovery</button></div>\n        </header>\n\n        <section id=\"overview\" class=\"hero panel\">\n          <div>\n            <p class=\"label\">CURRENT OPERATING STATE</p>\n            <div class=\"state\"><span class=\"pulse\"></span><strong>Not yet verified</strong></div>\n            <p class=\"hero-copy\">Jarvis has not supplied a trusted heartbeat, scheduler run, or delivered notification to this center. It must not be treated as active or 24/7.</p>\n          </div>\n          <div class=\"last-check\"><span>LAST OBSERVATION</span><strong>12 Nov 2026 · setup baseline</strong><small>Source: Operations Center configuration</small></div>\n        </section>\n\n        <section class=\"metric-grid\" aria-label=\"Status summary\">\n          <article class=\"metric\"><div class=\"metric-top\"><span class=\"dot unknown\"></span><span>Runtime health</span></div><strong>Unknown</strong><small>No authenticated service heartbeat received</small></article>\n          <article class=\"metric\"><div class=\"metric-top\"><span class=\"dot unknown\"></span><span>Deployment</span></div><strong>Unknown</strong><small>No Jarvis deployment is connected</small></article>\n          <article class=\"metric\"><div class=\"metric-top\"><span class=\"dot failed\"></span><span>Contact delivery</span></div><strong>Failed check</strong><small>No delivery receipt or reachable route on record</small></article>\n          <article class=\"metric\"><div class=\"metric-top\"><span class=\"dot unknown\"></span><span>Scheduled tasks</span></div><strong>Unknown</strong><small>No scheduler or job history connected</small></article>\n        </section>\n\n        <section id=\"evidence\" class=\"split section\">\n          <div><p class=\"eyebrow\">EVIDENCE LEDGER</p><h2>What we can honestly say</h2><p class=\"section-copy\">Status changes only when a connected source provides a timestamped result. A badge is never a claim that Jarvis is working.</p></div>\n          <div class=\"ledger panel\">\n            <div class=\"ledger-row heading\"><span>Check</span><span>State</span><span>Evidence</span></div>\n            <div class=\"ledger-row\"><span>Always-on worker</span><span class=\"status unknown-tag\">Unknown</span><span>Integration not configured</span></div>\n            <div class=\"ledger-row\"><span>Service uptime</span><span class=\"status unknown-tag\">Unknown</span><span>No heartbeat data</span></div>\n            <div class=\"ledger-row\"><span>Notification delivery</span><span class=\"status failed-tag\">Failed check</span><span>No verified recipient/channel</span></div>\n            <div class=\"ledger-row\"><span>Autonomous task loop</span><span class=\"status unknown-tag\">Unknown</span><span>No completed-run record</span></div>\n          </div>\n        </section>\n\n        <section id=\"tasks\" class=\"section two-col\">\n          <article class=\"panel padded\"><p class=\"eyebrow\">AUTONOMOUS TASK HISTORY</p><h2>No trustworthy run history yet</h2><p class=\"section-copy\">When connected, this ledger will retain task ID, trigger, started/finished time, outcome, linked recovery action, and a supporting log reference.</p><div class=\"empty\"><span>◌</span> Awaiting first signed event</div></article>\n          <article class=\"panel padded\"><p class=\"eyebrow\">ALERT ROUTING</p><h2>Why Jarvis has not reached you</h2><ol class=\"reason-list\"><li><span>01</span><div><strong>No verified notification channel</strong><small>There is no delivery receipt for push, email, SMS, or another chosen route.</small></div></li><li><span>02</span><div><strong>No active runtime proof</strong><small>A remote worker must send a recurring heartbeat to prove it survives when your Mac is off.</small></div></li><li><span>03</span><div><strong>No scheduler proof</strong><small>Scheduled tasks need a recent successful run and a retained execution record.</small></div></li></ol></article>\n        </section>\n\n        <section id=\"notifications\" class=\"section notification panel padded\"><div><p class=\"eyebrow\">NOTIFICATION VERIFICATION</p><h2>Deliver a test before relying on alerts.</h2><p class=\"section-copy\">Connect a notification provider, send a named test to your intended route, then require a delivery receipt and display it here. Do not enable escalation until that evidence exists.</p></div><button class=\"disabled\" disabled>Notification test unavailable — setup required</button></section>\n\n        <section id=\"recovery\" class=\"section recovery\">\n          <div><p class=\"eyebrow\">GUIDED RECOVERY</p><h2>Reconnect safely, one verified layer at a time.</h2><p class=\"section-copy\">These are instructions and checkpoints. Restarting or changing any production system requires your explicit approval in the connected environment.</p></div>\n          <div class=\"steps\">\n            <article class=\"step\"><span>1</span><div><h3>Connect the remote runtime</h3><p>Authorize only the worker or service that should run independently of your Mac. Record its health endpoint and heartbeat interval.</p><button class=\"outline\" data-modal=\"runtime\">Connection checklist</button></div></article>\n            <article class=\"step\"><span>2</span><div><h3>Verify the scheduler</h3><p>Register each task, its frequency, owner, timeout, and safe retry policy. Require at least one successful timestamped run.</p><button class=\"outline\" data-modal=\"scheduler\">Scheduler checklist</button></div></article>\n            <article class=\"step\"><span>3</span><div><h3>Prove notification delivery</h3><p>Choose your contact route, send a test, and store the provider’s delivery confirmation—not just a “sent” response.</p><button class=\"outline\" data-modal=\"notification\">Delivery checklist</button></div></article>\n            <article class=\"step\"><span>4</span><div><h3>Approve any corrective action</h3><p>Review the failure evidence, proposed scope, rollback plan, and service impact before a restart or configuration change is permitted.</p><button class=\"outline\" data-modal=\"approval\">Approval gate</button></div></article>\n          </div>\n        </section>\n        <footer><span>Jarvis Operations Center</span><span>Evidence-first · no unverified live claims · production changes require approval</span></footer>\n      </main>\n    </div>\n    <dialog id=\"modal\"><div class=\"modal-head\"><strong id=\"modal-title\">Checklist</strong><button id=\"close-modal\" aria-label=\"Close\">×</button></div><div id=\"modal-body\"></div></dialog>\n    <script>const copy={runtime:['Remote runtime connection checklist',['Confirm the runtime is cloud-hosted and independent of your Mac.','Record the service URL, owner, region, and a read-only health endpoint.','Set a heartbeat interval and a missed-heartbeat threshold.','Send a signed test heartbeat; keep its timestamp and response as evidence.']],scheduler:['Scheduler verification checklist',['List every autonomous task with its trigger, owner, timeout, and retry ceiling.','Run one harmless diagnostic task and retain its start, finish, and result.','Confirm task history survives a restart of the service.','Do not enable remediation tasks until the approval gate is configured.']],notification:['Notification delivery checklist',['Choose the destination channel and confirm the recipient identity.','Send a test with a unique reference code.','Require a delivery receipt or an equivalent provider status; “sent” is insufficient.','Record the receipt and test time in the evidence ledger.']],approval:['Production action approval gate',['Capture the failure evidence and exact affected service.','Write the proposed action, expected impact, and rollback procedure.','Request explicit approval before restarting, redeploying, or changing configuration.','After the action, run the same health and delivery checks again.']]};\nconst modal=document.querySelector('#modal');document.querySelectorAll('[data-modal]').forEach(b=>b.addEventListener('click',()=>{const [title,items]=copy[b.dataset.modal];document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-body').innerHTML='<ul>'+items.map(i=>'<li>'+i+'</li>').join('')+'</ul>';modal.showModal()}));document.querySelector('#close-modal').addEventListener('click',()=>modal.close());document.querySelectorAll('[data-scroll]').forEach(b=>b.addEventListener('click',()=>document.querySelector('#'+b.dataset.scroll).scrollIntoView()));\n</script>\n  </body>\n</html>\n";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === '/__health') {
      return Response.json({ status: 'ok', service: 'jarvis-operations-center', scope: 'dashboard-only' });
    }
    return new Response(page, {
      headers: {
        'content-type': 'text/html; charset=UTF-8',
        'cache-control': 'no-store',
        'x-content-type-options': 'nosniff',
        'referrer-policy': 'same-origin'
      }
    });
  }
};
